      box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.82), 0 12px 32px rgba(45, 78, 99, 0.08);
    }

    /* Preserve the one-screen guarantee on ordinary laptop displays. The
       high-screen expansion above must not trade a fuller canvas for page
       scrolling at 900–1080px heights. */
    @media (min-width: 768px) and (max-height: 1100px){
      .arch-slot .header{ margin-bottom: 1rem; }
      .arch-slot .diagram-container{
        padding: 0.875rem;
        padding-bottom: calc(0.875rem + var(--archify-nav-reserve));
      }
      .arch-slot .cards{ margin-top: 1rem; }
      .arch-slot .card{ padding: 1rem; }
    }
    @media (min-width: 768px) and (max-height: 920px){
      .arch-slot{ padding-block: 1.25rem; }
      .arch-slot .header{ margin-bottom: 0.875rem; }
      .arch-slot .cards{ margin-top: 0.75rem; }
    }

    .arch-slot[data-preset="blueprint"] .card{
      position: relative;
      border-color: var(--panel-border);
      border-radius: 0.3rem;
      background: var(--panel);
      box-shadow: none;
    }
    .arch-slot[data-preset="blueprint"] .card::before{
      content: "";
      position: absolute;
      top: -1px;
      left: 1rem;
      width: 2.5rem;
      border-top: 2px solid var(--frontend-stroke);
    }

    .arch-slot[data-preset="editorial"] .card{
      position: relative;
      border-radius: 0.28rem;
      background: var(--panel);
      box-shadow: 0 10px 28px color-mix(in srgb, #000 10%, transparent);
    }
    .arch-slot[data-preset="editorial"] .card::before{
      position: absolute;
      top: -1px;
      left: 1.25rem;
      width: 3.25rem;
      border-top: 3px solid var(--arrow-emphasis);
      content: "";
    }
    .arch-slot[data-preset="editorial"] .card-dot{ border-radius: 0; transform: rotate(45deg) scale(0.78); }

    .arch-slot .card-header{
      display: flex;
      align-items: center;
      gap: 0.5rem;
      margin-bottom: 0.75rem;
    }

    .arch-slot .card-dot{
      width: 8px;
      height: 8px;
      border-radius: 50%;
    }

    .arch-slot .card-dot.cyan{ background: var(--frontend-stroke); }
    .arch-slot .card-dot.emerald{ background: var(--backend-stroke); }
    .arch-slot .card-dot.violet{ background: var(--database-stroke); }
    .arch-slot .card-dot.amber{ background: var(--cloud-stroke); }
    .arch-slot .card-dot.rose{ background: var(--security-stroke); }
    .arch-slot .card-dot.orange{ background: var(--messagebus-stroke); }
    .arch-slot .card-dot.slate{ background: var(--external-stroke); }

    .arch-slot .card h3{ font-size: 0.875rem; font-weight: 600; color: var(--text); }

    .arch-slot .card ul{
      list-style: none;
      color: var(--text-muted);
      font-size: 0.75rem;
    }

    .arch-slot .card li{ margin-bottom: 0.375rem; }

    /* ==========================================================
       Print stylesheet — hide interactive controls, force light,
       drop the grid so the diagram doesn't waste ink, use landscape
       so wide diagrams fit, pack summary cards into 2 columns to
       avoid an orphan card on a trailing page.
       ========================================================== */
    @page{ size: landscape; margin: 1.5cm; }

    @media print{
      /* Force the FULL light palette — including component fills/strokes and
         lane/arrow colors — so printing from dark theme doesn't put neon
         strokes and translucent dark fills on white paper. */
      .arch-slot,
.arch-slot[data-theme="dark"],
.arch-slot[data-theme="light"]{
        --bg: #ffffff;
        --grid: transparent;
        --panel: #ffffff;
        --panel-border: #e2e8f0;
        --text: #0f172a;
        --text-muted: #475569;
        --text-dim: #94a3b8;
        --text-faint: #64748b;
        --mask: #ffffff;
        --lane-fill: rgba(248, 250, 252, 0.65);
        --lane-stroke: #cbd5e1;
        --arrow: #94a3b8;
        --arrow-emphasis: #059669;
        --frontend-fill:    rgba(34, 211, 238, 0.15);
        --frontend-stroke:  #0891b2;
        --backend-fill:     rgba(52, 211, 153, 0.18);
        --backend-stroke:   #059669;
        --database-fill:    rgba(167, 139, 250, 0.2);
        --database-stroke:  #7c3aed;
        --cloud-fill:       rgba(251, 191, 36, 0.18);
        --cloud-stroke:     #d97706;
        --security-fill:    rgba(251, 113, 133, 0.15);
        --security-stroke:  #e11d48;
        --messagebus-fill:  rgba(251, 146, 60, 0.15);
        --messagebus-stroke:#ea580c;
        --external-fill:    rgba(148, 163, 184, 0.18);
        --external-stroke:  #64748b;
      }
      .arch-slot{ background: #ffffff !important; padding: 0; }
      .arch-slot .container{ max-width: none; }
      .arch-slot .toolbar,
.arch-slot .diagram-nav,
.arch-slot .focus-chip,
.arch-slot .guided-views,
.arch-slot .archify-toast,
.arch-slot .no-print{ display: none !important; }
      .arch-slot .chapter-handoff-overlay{ display: none !important; }
      .arch-slot svg [data-node-id][data-chapter-role]{ opacity: 1 !important; }
      .arch-slot svg[data-chapter-preview] [data-node-id],
.arch-slot svg[data-chapter-preview] [data-edge-from]{ opacity: 1 !important; filter: none !important; }
      .arch-slot .diagram-container,
.arch-slot .card{ box-shadow: none; border-color: #e2e8f0; }
      .arch-slot .diagram-container{ --archify-nav-reserve: 0px !important; }
      .arch-slot[data-preset="signal-flow"] .diagram-container,
.arch-slot[data-preset="signal-flow"] .card{ background: #ffffff; }
      .arch-slot .cards{ grid-template-columns: 1fr 1fr; }
      /* Ensure elements break sensibly across pages */
      .arch-slot .card{ break-inside: avoid; page-break-inside: avoid; }
      .arch-slot .diagram-container{ break-inside: avoid; page-break-inside: avoid; }
      .arch-slot .diagram-container svg [data-detail]{
        opacity: 1 !important;
        pointer-events: auto !important;
      }
      .arch-slot .diagram-container svg [data-detail-anchor]{ transform: none !important; }
      .arch-slot .diagram-container svg[data-lens-active] [data-node-id],
.arch-slot .diagram-container svg[data-lens-active] [data-edge-from],
.arch-slot .diagram-container svg[data-legend-preview-active] [data-node-id],
.arch-slot .diagram-container svg[data-legend-preview-active] [data-edge-from]{
        opacity: 1 !important;
        filter: none !important;
      }
      .arch-slot[data-legend-bridge-runtime]{ display: none !important; }
      .arch-slot .semantic-lens-overlay{ display: none !important; }
      .arch-slot .relationship-hit-overlay{ display: none !important; }
      .arch-slot .relationship-pulse-overlay{ display: none !important; }
      .arch-slot .route-probe-overlay,
.arch-slot .route-journey-overlay{ display: none !important; }
      .arch-slot .story-trail-overlay,
.arch-slot .story-carrier-overlay{ display: none !important; }
      .arch-slot .diagram-container svg[data-focus-active] [data-node-id],
.arch-slot .diagram-container svg[data-focus-active] [data-edge-from],
.arch-slot .diagram-container svg[data-reach-active] [data-node-id],
.arch-slot .diagram-container svg[data-reach-active] [data-edge-from],
.arch-slot .diagram-container svg[data-story-beat] [data-story-step],
.arch-slot .diagram-container svg[data-story-beat] [data-edge-from][data-story-beat-step],
.arch-slot .diagram-container svg[data-route-active] [data-node-id],
.arch-slot .diagram-container svg[data-route-active] [data-edge-from]{
        opacity: 1 !important;
        filter: none !important;
        animation: none !important;
      }
      .arch-slot h1,
.arch-slot .subtitle{ color: #0f172a; }
    }

    /* ==========================================================
       TOOLBAR (theme toggle + export menu)
       ========================================================== */
    .arch-slot .toolbar{
      position: fixed;
      top: 1rem;
      right: 1rem;
      display: flex;
      align-items: center;
      gap: 0.5rem;
      padding: 0;
      border: 0;
      background: transparent;
      box-shadow: none;
      z-index: 100;
    }
    .arch-slot .toolbar button{
      background: var(--toolbar-bg);
      color: var(--toolbar-text);
      border: 1px solid var(--toolbar-border);
      padding: 0.5rem 0.875rem;
      border-radius: 0.625rem;
      font-family: inherit;
      font-size: 0.75rem;
      font-weight: 500;
      cursor: pointer;
      white-space: nowrap;
      backdrop-filter: blur(10px);
      box-shadow: 0 4px 14px rgba(0, 0, 0, 0.08);
      transition: background 0.15s, border-color 0.15s, color 0.15s;
      display: inline-flex;
      align-items: center;
      gap: 0.375rem;
      min-height: 2.75rem;
    }
    .arch-slot .toolbar button:hover{
      background: var(--toolbar-hover);
      border-color: color-mix(in srgb, var(--arrow) 62%, var(--toolbar-border));
    }
    .arch-slot .toolbar button[aria-expanded="true"],
.arch-slot .toolbar button[aria-pressed="true"]:not(#btn-theme){
