      position: relative;
      width: 2rem;
      height: 1.55rem;
      overflow: hidden;
      border: 1px solid #64748b;
      border-radius: 0.24rem;
      background: #0f172a;
      box-shadow: inset 0 0 0 1px rgba(255,255,255,0.04);
