      background: linear-gradient(90deg, #67e8f9, #c4b5fd);
      box-shadow: 0 0 8px #67e8f9;
    }
    .arch-slot .preset-option-swatch.signal-flow::after{
      top: calc(50% - 0.13rem);
      right: 0.28rem;
      width: 0.26rem;
