      background-size: 0.42rem 0.42rem;
    }
    .arch-slot .preset-option-swatch.blueprint::before{
      top: 0.34rem;
      right: 0.38rem;
      bottom: 0.34rem;
      left: 0.38rem;
      border: 1px solid #66d9ef;
    }
    .arch-slot .preset-option-swatch.editorial{
      border-color: #b8aa94;
      border-radius: 0.08rem;
      background: repeating-linear-gradient(0deg, #f2eee5 0 0.34rem, #d8d0c2 0.36rem, #f2eee5 0.38rem);
    }
    .arch-slot .preset-option-swatch.editorial::before{
      top: 0;
      bottom: 0;
      left: 0.42rem;
      width: 1px;
      background: #c9502d;
      opacity: 0.72;
    }
    .arch-slot .preset-option-swatch.editorial::after{
      top: 0.52rem;
